import React from 'react';
import MainHeading from '../../Components/Heading/MainHeading';
import NavBar from '../../Components/NavBar/NavBar';
import vid from "./v.mp4"
// import big from "/img/Big Bang.png"

function Home() {
  return (
    <div className='bg-gray-900'>
      <NavBar/>
      <video className="rounded-lg shadow-lg"
      width="800"
      controls>
        <source src={`${process.env.PUBLIC_URL}/vid/main.mp4`} srcSet={vid} type='videp/mp4' />
      </video>
    </div>
  );
}

export default Home;
